const makeTheme=(id,name,accent,bg,panel,extra={})=>({id,name,mode:'dark',format:'amago-theme-v1',author:'Âmago',colors:{bg,sidebar:bg,panel,raised:panel,hover:panel,border:'#2b3c53',text:'#bdcbdc',strong:'#ecf3ff',muted:'#8295ae',subtle:'#657992',accent,'accent-bg':panel,purple:'#b3a1ff',...extra}});
const nativeThemes=[makeTheme('orbital','Orbital','#78e2df','#0d1320','#172234'),makeTheme('cyberpunk','Cyberpunk','#f5ed42','#100f1c','#241b35',{border:'#654168',text:'#e0d8e9',strong:'#faf6b6',muted:'#b29bc4',subtle:'#857499',purple:'#ff4d99'}),makeTheme('midnight','Meia-noite','#aab9ff','#10111b','#1b2032'),makeTheme('forest','Floresta','#90d8a0','#101a16','#1c2d24',{border:'#345142',text:'#bfd5c6',strong:'#e3f4e9',muted:'#8ba896',purple:'#d7bd84'}),makeTheme('rose','Quartzo','#f0aecb','#20141e','#352233',{border:'#5d3b54',text:'#dbc4d5',strong:'#f9e7f3',muted:'#b295a9',purple:'#bea8f0'}),{...makeTheme('daylight','Alvorada','#247b85','#f0f5fb','#e0eaf6',{border:'#c6d5e7',text:'#435770',strong:'#172e4c',muted:'#58708f',subtle:'#7288a4',purple:'#7564ac'}),mode:'light'}];
function themeCatalog(){return [...nativeThemes,...(vault.communityThemes||[])]}
function applyTheme(){const selected=themeCatalog().find(t=>t.id===vault.skin)||(vault.theme==='light'?nativeThemes.at(-1):nativeThemes[0]);document.body.dataset.skin=selected.id;document.body.classList.toggle('theme-light',selected.mode==='light');vault.theme=selected.mode;for(const [key,value] of Object.entries(selected.colors))document.body.style.setProperty('--'+key,value);document.body.style.setProperty('--glass-rgb',selected.mode==='light'?'231,239,250':selected.id==='cyberpunk'?'20,13,29':selected.id==='forest'?'13,27,21':selected.id==='rose'?'29,14,25':'9,15,27')}
const themedRender=render;
render=function(){themedRender();applyTheme()};
actions.themes=()=>{modal('Aparência e temas',`<p>Escolha uma atmosfera para o seu espaço. O acrílico continua disponível no Windows.</p><div class="theme-grid">${themeCatalog().map(t=>`<button class="theme-tile ${vault.skin===t.id?'active':''}" data-theme-id="${esc(t.id)}" style="--tile-bg:${t.colors.bg};--tile-panel:${t.colors.panel};--tile-accent:${t.colors.accent}"><span class="theme-preview"><i></i><i></i><i></i></span><strong>${esc(t.name)}</strong><small>${esc(t.author)}</small></button>`).join('')}</div><div class="modal-actions"><button class="plain-button" id="import-theme">Importar tema .json</button><button class="plain-button" id="export-theme">Exportar tema atual</button></div><p>Temas da comunidade usam uma paleta de cores declarativa. Não executam scripts nem carregam CSS externo.</p>`);document.querySelectorAll('[data-theme-id]').forEach(b=>b.onclick=()=>{vault.skin=b.dataset.themeId;applyTheme();persist();render();actions.themes();if(window.amagoDesktop?.appearance)window.amagoDesktop.appearance({enabled:vault.appearance?.acrylic!==false,theme:vault.theme})});$('#import-theme').onclick=()=>themeInput.click();$('#export-theme').onclick=()=>download('amago-'+(vault.skin||'orbital')+'.theme.json',JSON.stringify(themeCatalog().find(t=>t.id===vault.skin)||nativeThemes[0],null,2),'application/json')};
const themeInput=document.createElement('input');themeInput.type='file';themeInput.accept='.json';themeInput.hidden=true;document.body.append(themeInput);themeInput.onchange=async()=>{try{const file=themeInput.files[0];if(!file)return;if(file.size>50000)throw Error('O tema deve ter até 50 KB.');const theme=AmagoExtensions.theme(JSON.parse(await file.text()));theme.id='community-'+theme.id.replace(/^community-/,'');vault.communityThemes??=[];vault.communityThemes=vault.communityThemes.filter(t=>t.id!==theme.id);vault.communityThemes.push(theme);vault.skin=theme.id;applyTheme();persist();render();actions.themes();window.amagoDesktop?.appearance?.({enabled:vault.appearance?.acrylic!==false,theme:vault.theme});toast('Tema importado.')}catch(e){toast(e.message)}finally{themeInput.value=''}};
const pluginRuntime=new Map();
function activeDocument(){if(workbench.source==='project'){const f=workbench.file;if(!AmagoFiles.editable(f))throw Error('Abra um documento de texto primeiro.');return {id:f.path,title:f.name,body:f.body,source:'project'}}const n=note();if(!n)throw Error('Abra uma nota primeiro.');return {id:n.id,title:n.title,body:n.body,source:'vault'}}
function proposePluginContent(plugin,body){if(typeof body!=='string'||body.length>1000000)throw Error('O conteúdo proposto deve ter até 1 milhão de caracteres.');if($('#plugin-proposal'))throw Error('Já existe uma proposta aguardando revisão.');const original=activeDocument();return new Promise(resolve=>{modal('Revisar alteração do plugin',`<div id="plugin-proposal"><p><strong>${esc(plugin.name)}</strong> propõe substituir o conteúdo de <strong>${esc(original.title)}</strong>.</p><div class="plugin-diff"><div><small>ATUAL</small><pre>${esc(original.body)}</pre></div><div><small>PROPOSTA</small><pre>${esc(body)}</pre></div></div><div class="modal-actions"><button class="plain-button" id="reject-plugin">Descartar</button><button class="solid-button" id="accept-plugin">Aplicar alteração</button></div></div>`);let done=false;const finish=value=>{if(done)return;done=true;observer.disconnect();resolve(value)};const observer=new MutationObserver(()=>{if(!$('#plugin-proposal'))finish({applied:false})});observer.observe($('#modal-root'),{childList:true,subtree:true});$('#reject-plugin').onclick=()=>{finish({applied:false});closeModal()};$('#accept-plugin').onclick=async()=>{try{const current=activeDocument();if(current.id!==original.id||current.source!==original.source||current.body!==original.body)throw Error('A nota mudou desde a proposta. Execute o comando novamente.');if(original.source==='project'){workbench.file.body=body;workbench.file.dirty=true;if(!(await saveProjectFile()))return}else{const n=note();n.body=body;n.updated=stamp();persist()}finish({applied:true});closeModal();renderMain()}catch(e){toast(e.message)}}})}
function stopPlugin(id){const runtime=pluginRuntime.get(id);if(runtime){clearTimeout(runtime.timeout);runtime.port.close();runtime.frame.remove();runtime.surface?.remove();pluginRuntime.delete(id);if(typeof updatePluginToolbar==='function')updatePluginToolbar()}for(let i=commandList.length-1;i>=0;i--)if(commandList[i][1].startsWith('plugin:'+id+':'))commandList.splice(i,1);for(const name of Object.keys(actions))if(name.startsWith('plugin:'+id+':'))delete actions[name]}
function startPlugin(plugin){stopPlugin(plugin.id);if(!plugin.enabled)return;const frame=document.createElement('iframe');frame.sandbox='allow-scripts';frame.src='plugin-frame.html';frame.hidden=true;frame.setAttribute('title','Plugin isolado: '+plugin.name);const channel=new MessageChannel(),runtime={frame,port:channel.port1,ready:false,timeout:null};pluginRuntime.set(plugin.id,runtime);let calls=0,last=Date.now();runtime.port.onmessage=async e=>{if(pluginRuntime.get(plugin.id)!==runtime||!plugin.enabled)return;const data=e.data;if(!data||typeof data!=='object')return;if(data.type==='ready'){clearTimeout(runtime.timeout);runtime.ready=true;document.querySelector('[data-plugin-status="'+plugin.id+'"]')?.replaceChildren(document.createTextNode('Ativo'));for(const command of plugin.commands){if(!Array.isArray(data.commands)||!data.commands.includes(command.id))continue;const action='plugin:'+plugin.id+':'+command.id;actions[action]=()=>runtime.port.postMessage({type:'invoke',command:command.id});commandList.push([plugin.name+' · '+command.title,action,''])}pluginReady(plugin,runtime);return}if(data.type==='error'){clearTimeout(runtime.timeout);if(!runtime.ready){runtime.failed=true;document.querySelector('[data-plugin-status="'+plugin.id+'"]')?.replaceChildren(document.createTextNode('Falha ao iniciar'))}toast(plugin.name+': '+String(data.message).slice(0,300));return}if(data.type!=='request')return;if(Date.now()-last>1000){calls=0;last=Date.now()}if(++calls>60){runtime.port.postMessage({type:'result',id:data.id,error:'Muitas solicitações. Tente novamente em um segundo.'});return};try{let value;if(data.method==='message'){toast(plugin.name+': '+String(data.value).slice(0,300));value=true}else value=await extensionRequest(plugin,runtime,data.method,data.value);runtime.port.postMessage({type:'result',id:data.id,value})}catch(error){runtime.port.postMessage({type:'result',id:data.id,error:error.message})}};frame.onload=()=>frame.contentWindow.postMessage({type:'amago-plugin-boot',code:plugin.code,commands:plugin.commands.map(c=>c.id)},'*',[channel.port2]);attachPluginFrame(plugin,runtime);runtime.timeout=setTimeout(()=>{if(!runtime.ready){toast('O plugin '+plugin.name+' não iniciou. Verifique o pacote.');runtime.failed=true;document.querySelector('[data-plugin-status="'+plugin.id+'"]')?.replaceChildren(document.createTextNode('Falha ao iniciar'));stopPlugin(plugin.id)}},15000)}
const permissionLabel=p=>({'note:read':'Ler a nota ou Markdown atualmente aberto','note:write':'Propor alterações, sempre com revisão antes de aplicar','workspace:read':'Listar, ler e navegar pelos documentos do workspace aberto','ui:panel':'Exibir painéis próprios com HTML, CSS e interações','storage':'Guardar dados próprios do plugin neste dispositivo'}[p]);
actions.plugins=()=>{vault.plugins??=[];modal('Plugins e extensões',`<p>Instale pacotes de terceiros nos formatos <code>amago-plugin-v1</code> e <code>amago-plugin-v2</code>. Cada plugin executa isolado, sem rede e sem acesso direto às pastas.</p><div class="plugin-list">${vault.plugins.map(p=>`<div class="plugin-card"><div><strong>${esc(p.name)}</strong><small>v${esc(p.version)} · ${esc(p.author)} · <span data-plugin-status="${esc(p.id)}">${p.enabled?(pluginRuntime.get(p.id)?.ready?'Ativo':pluginRuntime.get(p.id)?.failed?'Falha ao iniciar':'Iniciando…'):'Desativado'}</span></small><p>${esc(p.description)}</p>${p.permissions.map(x=>`<span class="permission-badge">${esc(permissionLabel(x))}</span>`).join('')}</div><div class="plugin-actions">${p.settings?.length?`<button class="plain-button" data-plugin-settings="${esc(p.id)}">Configurar</button>`:''}<button class="plain-button" data-plugin-toggle="${esc(p.id)}">${p.enabled?'Desativar':'Ativar'}</button><button class="plain-button" data-plugin-remove="${esc(p.id)}">Remover</button></div></div>`).join('')||'<p>Nenhum plugin instalado.</p>'}</div><div class="modal-actions"><button class="solid-button" id="import-plugin">Instalar pacote .json</button><button class="plain-button" id="plugin-example">Baixar plugin de exemplo</button></div><p>Os comandos dos plugins ativos aparecem na paleta <kbd>Ctrl Shift P</kbd>. Plugins do Obsidian não são compatíveis diretamente.</p>`);document.querySelectorAll('[data-plugin-settings]').forEach(b=>b.onclick=()=>openPluginSettings(vault.plugins.find(p=>p.id===b.dataset.pluginSettings)));$('#import-plugin').onclick=()=>pluginInput.click();$('#plugin-example').onclick=()=>download('contador.amago-plugin.json',JSON.stringify(examplePlugin,null,2),'application/json');document.querySelectorAll('[data-plugin-toggle]').forEach(b=>b.onclick=()=>{const p=vault.plugins.find(p=>p.id===b.dataset.pluginToggle);if(p.enabled){p.enabled=false;stopPlugin(p.id);persist();actions.plugins()}else reviewPlugin(p,false)});document.querySelectorAll('[data-plugin-remove]').forEach(b=>b.onclick=()=>{stopPlugin(b.dataset.pluginRemove);vault.plugins=vault.plugins.filter(p=>p.id!==b.dataset.pluginRemove);persist();actions.plugins()})};
function reviewPlugin(plugin,install=true){modal('Permissões do plugin',`<h3>${esc(plugin.name)} <small>v${esc(plugin.version)}</small></h3><p>${esc(plugin.description)}</p><p>Autor declarado: ${esc(plugin.author)}</p><ul>${plugin.permissions.map(p=>`<li>${esc(permissionLabel(p))}</li>`).join('')||'<li>Sem acesso ao conteúdo das notas.</li>'}</ul><p>O código roda em uma janela isolada, sem acesso à rede, direto ao armazenamento do app ou aos arquivos do computador. As permissões acima definem os dados disponíveis pela API. Instale pacotes de autores em quem você confia.</p><div class="modal-actions"><button class="plain-button" data-action="plugins">Cancelar</button><button class="solid-button" id="approve-plugin">Conceder permissões e ativar</button></div>`);$('#approve-plugin').onclick=()=>{vault.plugins??=[];stopPlugin(plugin.id);plugin.enabled=true;if(install){vault.plugins=vault.plugins.filter(p=>p.id!==plugin.id);vault.plugins.push(plugin)}persist();startPlugin(plugin);actions.plugins()}}
const examplePlugin={format:'amago-plugin-v1',id:'contador',name:'Contador de palavras',version:'1.0.0',author:'Âmago',description:'Exemplo de plugin: conta as palavras da nota aberta.',permissions:['note:read'],commands:[{id:'count',title:'Contar palavras'}],code:"export default function(api){api.registerCommand('count',async()=>{const note=await api.getActiveNote();const words=note.body.trim().split(/\\s+/).filter(Boolean).length;await api.showMessage(note.title+': '+words+' palavras');});}"};
const pluginInput=document.createElement('input');pluginInput.type='file';pluginInput.accept='.json';pluginInput.hidden=true;document.body.append(pluginInput);pluginInput.onchange=async()=>{try{const file=pluginInput.files[0];if(!file)return;if(file.size>250000)throw Error('O pacote deve ter até 250 KB.');reviewPlugin(AmagoExtensions.plugin(JSON.parse(await file.text())))}catch(e){toast(e.message)}finally{pluginInput.value=''}};
const settingsWithAppearance=actions.settings;
actions.settings=()=>{settingsWithAppearance();$('#theme')?.closest('.setting-row')?.remove();$('.modal-body').insertAdjacentHTML('afterbegin',`<div class="personalization-links"><button class="plain-button" data-action="themes">${icon('layers')}Temas e comunidade</button><button class="plain-button" data-action="plugins">${icon('core')}Plugins e extensões</button></div>`);$('#theme')?.addEventListener('change',e=>{vault.skin=e.target.value==='light'?'daylight':'orbital';applyTheme();persist();window.amagoDesktop?.appearance?.({enabled:vault.appearance?.acrylic!==false,theme:vault.theme})})};
commandList.push(['Temas e comunidade','themes',''],['Plugins e extensões','plugins','']);
