actions.commands=()=>{commandsWithProject();if(workbench.source==='project')$('.modal-body').insertAdjacentHTML('beforeend',commandList.filter(c=>c[1].startsWith('plugin:')).map(c=>`<button class="search-result" data-command="${esc(c[1])}">${icon('core')}<strong>${esc(c[0])}</strong></button>`).join(''))};
let loadedPlugins=false;
const bootPersonalization=()=>{applyTheme();if(loadedPlugins)return;loadedPlugins=true;for(const raw of vault.plugins||[]){try{const p=AmagoExtensions.plugin(raw);if(raw.enabled){Object.assign(raw,p,{enabled:true});startPlugin(raw)}}catch{raw.enabled=false}}};
window.addEventListener('amago-ready',bootPersonalization);if(window.amagoReady||!window.amagoDesktop)bootPersonalization();

// API v2 host. Capabilities are checked for every call, not just during activation.
function pluginSettings(plugin){vault.pluginSettings??={};try{return AmagoExtensions.settingsValues(plugin,vault.pluginSettings[plugin.id]||{})}catch{return AmagoExtensions.settingsValues(plugin)}}
function attachPluginFrame(plugin,runtime){const surface=document.createElement('aside');surface.className='plugin-surface';surface.hidden=true;surface.setAttribute('aria-label','Painel do plugin '+plugin.name);const header=document.createElement('header'),title=document.createElement('strong'),close=document.createElement('button');title.textContent=plugin.name;close.textContent='×';close.className='icon-button';close.setAttribute('aria-label','Fechar painel do plugin');close.onclick=()=>{surface.hidden=true;runtime.port.postMessage({type:'event',name:'view:close',value:{}})};header.append(title,close);surface.append(header,runtime.frame);runtime.surface=surface;runtime.panelTitle=title;document.body.append(surface)}
function pluginScope(){return workbench.source==='project'?'project:'+workbench.project?.root:'vault'}
let pluginSelection=null,pluginEventTimer;
function rememberPluginSelection(event){const editor=event.target;if(!editor.matches?.('#editor,#project-editor,[data-pane-editor]'))return;try{const doc=activeDocument();if(editor.value!==doc.body)return;pluginSelection={id:doc.id,source:doc.source,body:doc.body,start:editor.selectionStart,end:editor.selectionEnd}}catch{}}
for(const name of ['select','keyup','pointerup','input'])document.addEventListener(name,rememberPluginSelection,true);
async function extensionRequest(plugin,runtime,method,value){
 const permission={'note:read':'note:read','note:write':'note:write','selection:read':'note:read','selection:write':'note:write','workspace:list':'workspace:read','workspace:document':'workspace:read','workspace:open':'workspace:read','ui:panel':'ui:panel','ui:hide':'ui:panel','storage:get':'storage','storage:set':'storage','settings:get':null,'settings:set':null};
 if(!Object.hasOwn(permission,method))throw Error('Método não suportado.');if(permission[method]&&!plugin.permissions.includes(permission[method]))throw Error('Permissão não concedida: '+permission[method]);
 if(method==='note:read')return {...activeDocument(),metadata:AmagoSearch.metadata(activeDocument().body)};
 if(method==='note:write')return proposePluginContent(plugin,value);
 if(method.startsWith('selection:')){const doc=activeDocument(),anchor=pluginSelection;if(!anchor||anchor.id!==doc.id||anchor.source!==doc.source||anchor.body!==doc.body)throw Error('Selecione texto no editor antes de executar o comando.');if(method==='selection:read')return {id:doc.id,source:doc.source,start:anchor.start,end:anchor.end,text:doc.body.slice(anchor.start,anchor.end)};if(typeof value!=='string'||value.length>1000000)throw Error('Texto inválido.');return proposePluginContent(plugin,doc.body.slice(0,anchor.start)+value+doc.body.slice(anchor.end))}
 if(method==='workspace:list'){if(workbench.source==='project'&&discovery.indexing)await discovery.indexPromise;return discoveryDocs().filter(d=>!d.kind||AmagoFiles.editable(d)).slice(0,3000).map(d=>({id:docId(d),title:d.title||d.name,path:d.path||d.folder,kind:d.kind||'markdown',tags:AmagoSearch.documentData(d).tags}))}
 if(method==='workspace:document'||method==='workspace:open'){if(typeof value!=='string')throw Error('Identificador inválido.');const source=workbench.source,scope=pluginScope(),doc=source==='project'?projectFiles().find(d=>d.path===value&&AmagoFiles.editable(d)):vault.notes.find(d=>d.id===value);if(!doc)throw Error('Documento fora do workspace atual.');if(method==='workspace:open'){if(source==='project')await openProjectFile(value);else await openNote(value);return true}let content=doc;if(source==='project'){content=typeof studio!=='undefined'&&studio.files.get(value)||await window.projectAdapter.read(value);if(content.error)throw Error(content.error)}if(scope!==pluginScope())throw Error('O workspace mudou durante a leitura.');if(content.body.length>1000000)throw Error('A API limita documentos a 1 milhão de caracteres.');return {id:value,title:doc.title||doc.name,body:content.body,source,metadata:AmagoSearch.metadata(content.body)}}
 if(method==='settings:get')return pluginSettings(plugin);
 if(method==='settings:set'){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Configurações inválidas.');vault.pluginSettings??={};vault.pluginSettings[plugin.id]=AmagoExtensions.settingsValues(plugin,{...pluginSettings(plugin),...value});persist();runtime.port.postMessage({type:'event',name:'settings:change',value:vault.pluginSettings[plugin.id]});return vault.pluginSettings[plugin.id]}
 if(method==='storage:get')return vault.pluginData?.[plugin.id]??null;
 if(method==='storage:set'){const json=JSON.stringify(value??null);if(new TextEncoder().encode(json).length>65536)throw Error('O armazenamento do plugin tem limite de 64 KiB.');vault.pluginData??={};vault.pluginData[plugin.id]=JSON.parse(json);persist();return true}
 if(method==='ui:panel'){runtime.panelTitle.textContent=plugin.name+(value?.title?' · '+String(value.title).slice(0,80):'');runtime.surface.style.setProperty('--plugin-width',Math.max(280,Math.min(900,Number(value?.width)||420))+'px');runtime.surface.hidden=false;runtime.frame.hidden=false;runtime.frame.focus();return true}
 if(method==='ui:hide'){runtime.surface.hidden=true;return true}
}
function pluginReady(plugin,runtime){const theme=themeCatalog().find(t=>t.id===vault.skin)||nativeThemes[0];runtime.port.postMessage({type:'event',name:'theme:change',value:{id:theme.id,colors:theme.colors}});runtime.port.postMessage({type:'event',name:'settings:change',value:pluginSettings(plugin)});updatePluginToolbar()}
function updatePluginToolbar(){let button=$('#plugin-tools');const commands=(vault.plugins||[]).filter(p=>p.enabled&&pluginRuntime.get(p.id)?.ready).flatMap(p=>(p.toolbar||[]).map(id=>({plugin:p,command:p.commands.find(c=>c.id===id)})));if(!commands.length){button?.remove();return}if(!button){button=document.createElement('button');button.id='plugin-tools';button.className='plugin-toolbar-button';button.textContent='Extensões';button.title='Comandos dos plugins';$('.header-right').prepend(button)}button.onclick=()=>{modal('Extensões do workspace',commands.map(({plugin,command})=>`<button class="search-result" data-extension-invoke="${esc(plugin.id+':'+command.id)}">${icon('core')}<span><strong>${esc(command.title)}</strong><small>${esc(plugin.name)}</small></span></button>`).join(''));document.querySelectorAll('[data-extension-invoke]').forEach(b=>b.onclick=()=>{const [id,command]=b.dataset.extensionInvoke.split(':');closeModal();pluginRuntime.get(id)?.port.postMessage({type:'invoke',command})})}}
function openPluginSettings(plugin){const values=pluginSettings(plugin);modal('Configurar '+plugin.name,`<form class="plugin-settings-form" id="plugin-settings-form">${plugin.settings.map(f=>`<label><span>${esc(f.label)}</span>${f.type==='boolean'?`<input name="${f.key}" type="checkbox" ${values[f.key]?'checked':''}>`:f.type==='select'?`<select class="field" name="${f.key}">${f.options.map(o=>`<option ${o===values[f.key]?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input class="field" name="${f.key}" type="${f.type==='number'?'number':'text'}" value="${esc(values[f.key])}" ${f.type==='number'?`min="${f.min}" max="${f.max}" step="any"`:'maxlength="2000"'}>`}</label>`).join('')}<div class="modal-actions"><button class="solid-button">Salvar configurações</button></div></form>`);$('#plugin-settings-form').onsubmit=e=>{e.preventDefault();try{const values={};for(const f of plugin.settings){const input=e.target.elements[f.key];values[f.key]=f.type==='boolean'?input.checked:f.type==='number'?Number(input.value):input.value}vault.pluginSettings??={};vault.pluginSettings[plugin.id]=AmagoExtensions.settingsValues(plugin,values);persist();pluginRuntime.get(plugin.id)?.port.postMessage({type:'event',name:'settings:change',value:values});actions.plugins()}catch(error){toast(error.message)}}}
let previousPluginScope='',previousPluginTheme='';
function publishPluginEvents(){const scope=pluginScope(),theme=themeCatalog().find(t=>t.id===vault.skin)||nativeThemes[0];for(const plugin of vault.plugins||[]){const runtime=pluginRuntime.get(plugin.id);if(!runtime?.ready||!plugin.enabled)continue;const emit=(name,value)=>runtime.port.postMessage({type:'event',name,value});if(plugin.permissions.includes('note:read'))try{const doc=activeDocument();emit('document:change',{id:doc.id,title:doc.title,source:doc.source})}catch{}if(scope!==previousPluginScope&&plugin.permissions.includes('workspace:read'))emit('workspace:change',{source:workbench.source});if(theme.id!==previousPluginTheme)emit('theme:change',{id:theme.id,colors:theme.colors})}previousPluginScope=scope;previousPluginTheme=theme.id}
function schedulePluginEvents(){clearTimeout(pluginEventTimer);pluginEventTimer=setTimeout(publishPluginEvents,250)}
const pluginEventRender=render;render=function(){pluginEventRender();schedulePluginEvents()};document.addEventListener('input',e=>{if(e.target.matches('#editor,#project-editor,[data-pane-editor]'))schedulePluginEvents()});document.addEventListener('focusin',e=>{if(e.target.matches('[data-pane-editor]'))schedulePluginEvents()});
